use std::{fs,path::Path,collections::BTreeMap};use serde_json::{Value,json};use sha2::{Digest,Sha256};
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let r=Path::new("/tmp/zopro-local-difference-basis");let p=r.join("probe.rs");let old=fs::read_to_string(&p).unwrap();fs::write(r.join("probe-initial.rs"),&old).unwrap();let anchor="include!(\"native-helpers.rs\");";assert_eq!(old.matches(anchor).count(),1);let fixed=old.replace(anchor,r#"mod native_helpers {
    include!("native-helpers.rs");
    pub(super) fn signed(s:&[u64;4],w:usize,bits:usize)->i16{booth_digit(s,w,bits)}
    pub(super) fn unsigned(s:&[u64;4],w:usize,bits:usize)->i16{unsigned_digit(s,w,bits)}
}
use native_helpers::{phi_split,signed as booth_digit,unsigned as unsigned_digit};"#);fs::write(&p,fixed).unwrap();let pins:BTreeMap<String,String>=serde_json::from_slice(&fs::read(r.join("input-pins.json")).unwrap()).unwrap();for(p,h)in &pins{let at=if *p==r.join("probe.rs").to_str().unwrap(){r.join("probe-initial.rs")}else{p.into()};assert_eq!(hash(at),*h);}
let mut next=pins.iter().map(|(p,_)|(p.clone(),hash(p))).collect::<BTreeMap<_,_>>();for name in ["probe-initial.rs","repair-link.rs"]{let p=r.join(name);next.insert(p.to_str().unwrap().into(),hash(&p));}let mut plan:Value=serde_json::from_slice(&fs::read(r.join("plan.json")).unwrap()).unwrap();plan["source_pins"]=json!(r.join("input-pins-v2.json"));fs::write(r.join("input-pins-v2.json"),serde_json::to_vec_pretty(&next).unwrap()).unwrap();fs::write(r.join("plan-v2.json"),serde_json::to_vec_pretty(&plan).unwrap()).unwrap();fs::write(r.join("link-repair.json"),serde_json::to_vec_pretty(&json!({"reason":"Accepted phi helper retains pub(super); including it at crate root fails Rust visibility checking","repair":"Nest byte-identical helper source in module and add scalar digit call wrappers only","source_arithmetic_and_protocol_unchanged":true,"before_census_execution":true,"original_pins_verified_with_initial_probe_relocation":205,"corrected_pins":next.len()})).unwrap()).unwrap();println!("Link-only module wrapper repair; extractedhelperbytes unchanged, original205/corrected{}pins",next.len());}
